import {ACCOUNT_ID} from './poller.mjs';
import {loadLanData,datePreset,validateDateRange,getShanghaiDate} from './lan-data.mjs';
import {ensureOperator} from './operator-ui.mjs';
import {BATCH_LIMIT,batchMetric,filterBatchPlans} from './batch-model.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={pending:'等待提交',submitting:'正在提交',success:'平台已确认',failed:'失败，已停止后续',uncertain:'结果未确认，请核查',skipped:'未提交',ready:'核对通过',invalid:'核对未通过'};
const storageKey='qianchuan:1000000000000000:last-batch-boost';
async function request(path,body){const r=await fetch('/lan-api/operation/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})}),j=await r.json();if(!r.ok)throw new Error(j.error?.message||'批量请求未完成，请检查状态后再操作');return j;}
export function openBatchBoost({from,to,selectedIds=[],notify,onSuccess=()=>{}}){
 const d=document.createElement('dialog');d.className='operation-dialog batch-dialog';d.setAttribute('aria-label','批量计划一键起量');
 const initial={from:from||getShanghaiDate(),to:to||getShanghaiDate()};let data=null,selected=new Set(),matched=[],page=1,loading=false,working=false,prepared=null,job=null,timer,revision=0,first=true;
 d.innerHTML=`<header><div><h2>批量计划一键起量</h2><small>选择具体计划，统一设置额外预算与时长，核对后逐条提交。</small></div><button data-close aria-label="关闭批量起量">×</button></header><section class="batch-selection"><div class="batch-range"><label>统计开始日期<input id="batch-from" type="date" value="${esc(initial.from)}" max="${getShanghaiDate()}"></label><label>统计结束日期<input id="batch-to" type="date" value="${esc(initial.to)}" max="${getShanghaiDate()}"></label><select id="batch-preset" aria-label="批量统计快捷日期"><option value="custom">自定义</option><option value="today">今天</option><option value="yesterday">昨天</option><option value="last7">近7天</option><option value="last30">近30天</option></select><button id="batch-query" type="button">查询区间数据</button></div><p id="batch-range-state" role="status"></p><div class="batch-filters"><label>计划名称或ID<input id="batch-search" type="search" placeholder="搜索具体计划"></label><label>投放状态<select id="batch-status"><option value="all">全部状态</option></select></label>${[['spend','基础消耗（元）'],['roi','综合营销ROI'],['orders','净成交订单数'],['budget','当前日预算（元）']].map(([key,label])=>`<fieldset><legend>${label}</legend><input data-bound="${key}Min" type="number" min="0" step="any" placeholder="最低" aria-label="${label}下限"><span>至</span><input data-bound="${key}Max" type="number" min="0" step="any" placeholder="最高" aria-label="${label}上限"></fieldset>`).join('')}</div><div class="batch-selection-bar"><span id="batch-count"></span><button id="batch-pick">勾选本页</button><button id="batch-prune">移除筛选外已选</button><button id="batch-clear">清空勾选</button></div><div class="batch-grid"><table><thead><tr><th>选择</th><th>计划</th><th>状态</th><th>日预算</th><th>基础消耗</th><th>实际ROI</th><th>净成交订单</th></tr></thead><tbody id="batch-rows"></tbody></table></div><div id="batch-pages" class="batch-pages"></div><p><small>统计区间影响消耗、ROI和订单数；日预算与状态为当前采集值。缺失指标显示“—”，启用该指标筛选时自动排除。单批最多${BATCH_LIMIT}条，避免集中提交。</small></p><section class="batch-task-inputs"><label>每条计划的额外起量预算（元）<input id="batch-budget" inputmode="decimal" placeholder="至少100元，不能超过任何所选计划日预算"></label><label>起量时长（小时）<input id="batch-duration" type="number" min="0.5" max="24" step="0.5" value="4"></label><label>任务名称前缀<input id="batch-name" maxlength="20" value="批量起量_${getShanghaiDate().replaceAll('-','')}"></label></section><p id="batch-total"></p></section><section id="batch-review" hidden></section><p class="operation-error" role="alert"></p><footer><button id="batch-history" type="button">查看最近批次</button><button id="batch-back" hidden>返回选择</button><button id="batch-cancel-job" hidden>停止后续提交</button><button data-close>关闭</button><button id="batch-primary" class="primary">核对所选计划</button></footer>`;
 document.body.append(d);d.showModal();const $=s=>d.querySelector(s),error=e=>$('.operation-error').textContent=e;
 const currentFilters=()=>({search:$('#batch-search').value,status:$('#batch-status').value,...Object.fromEntries([...d.querySelectorAll('[data-bound]')].map(n=>[n.dataset.bound,n.value]))});
 function render(){
  try{matched=filterBatchPlans(data?.plans||[],currentFilters());error('');}catch(e){matched=[];error(e.message);}
  const pages=Math.max(1,Math.ceil(matched.length/20));page=Math.min(page,pages);const visible=matched.slice((page-1)*20,page*20),inside=new Set(matched.map(p=>p.id)),hidden=[...selected].filter(id=>!inside.has(id)).length;
  $('#batch-count').textContent=`匹配 ${matched.length} 条 · 已选 ${selected.size}/${BATCH_LIMIT}`+(hidden?`（${hidden}条不在当前筛选中）`:'');
  $('#batch-rows').innerHTML=visible.map(p=>`<tr class="${selected.has(p.id)?'picked':''}"><td><input type="checkbox" data-pick="${esc(p.id)}" ${selected.has(p.id)?'checked':''} aria-label="批量选择计划 ${esc(p.name)}"></td><td>${esc(p.name)}<small>ID：${esc(p.id)}</small></td><td>${esc(p.statusText)}</td><td>${p.budget.toFixed(2)}</td>${['spend','roi','orders'].map(k=>`<td>${batchMetric(p,k)===null?'—':batchMetric(p,k).toLocaleString('zh-CN',{maximumFractionDigits:2})}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">没有匹配的计划</td></tr>';
  $('#batch-pages').innerHTML=`<button data-batch-page="${page-1}" ${page<=1?'disabled':''}>上一页</button><span>${page} / ${pages}</span><button data-batch-page="${page+1}" ${page>=pages?'disabled':''}>下一页</button>`;
  $('#batch-primary').disabled=loading||working||!selected.size||!data?.complete;const budget=Number($('#batch-budget').value);$('#batch-total').textContent=`已选 ${selected.size} 条`+(budget>0?` · 额外预算合计 ${(budget*selected.size).toFixed(2)} 元`:'');
 }
 async function load(){if(working)return;let range;try{range=validateDateRange($('#batch-from').value,$('#batch-to').value);}catch(e){error(e.message);return;}const rev=++revision;loading=true;$('#batch-query').disabled=true;$('#batch-range-state').textContent='正在查询所选日期区间，请稍候…';render();
  try{const next=await loadLanData({accountId:ACCOUNT_ID,...range,page:1,pageSize:100000,product:'selected',status:'all',sortField:'create_time',sortType:'desc',force:true});if(rev!==revision||!d.open)return;if(next.accountId!==ACCOUNT_ID||!next.complete||next.from!==range.from||next.to!==range.to||next.rangeQuery?.stale)throw new Error('该区间未取得完整的最新结果，请重新查询后选择');data=next;selected.clear();if(first){if(selectedIds.length>BATCH_LIMIT)notify('主列表已勾选超过20条，请在批量窗口重新选择，未自动截断。');else for(const id of selectedIds)if(data.plans.some(p=>p.id===id))selected.add(id);first=false;}page=1;$('#batch-status').innerHTML='<option value="all">全部状态</option>'+[...new Set(data.plans.map(p=>p.statusText))].map(s=>`<option>${esc(s)}</option>`).join('');$('#batch-range-state').textContent=`当前统计：${data.from} 至 ${data.to} · 已取得 ${data.plans.length} 条计划。改变区间重新查询后会清空勾选。`;}
  catch(e){data=null;selected.clear();$('#batch-range-state').textContent='查询失败：'+e.message;error(e.message);}finally{if(rev===revision){loading=false;$('#batch-query').disabled=false;render();}}
 }
 function showJob(value){job=value;prepared=null;$('.batch-selection').hidden=true;$('#batch-review').hidden=false;$('#batch-primary').hidden=true;$('#batch-back').hidden=true;$('#batch-cancel-job').hidden=job.status!=='running';$('#batch-cancel-job').disabled=job.cancelRequested;$('#batch-review').innerHTML=`<h3>${job.status==='running'?'批量起量正在执行':'批次处理结果'}</h3><p>额外预算合计 ${job.totalBudget.toFixed(2)} 元 · 成功 ${job.items.filter(i=>i.status==='success').length} / ${job.items.length} 条</p><p>${esc(job.message||'逐条提交，关闭窗口不会取消；可停止尚未提交的计划。')}</p><div class="batch-grid"><table><thead><tr><th>计划</th><th>额外预算</th><th>结果</th></tr></thead><tbody>${job.items.map(i=>`<tr><td>${esc(i.name)}<small>${i.id}</small></td><td>${i.budget.toFixed(2)}元</td><td>${labels[i.status]}${i.error?'<small>'+esc(i.error)+'</small>':''}</td></tr>`).join('')}</tbody></table></div>`;if(job.status!=='running'){clearTimeout(timer);onSuccess();}else timer=setTimeout(()=>void pollJob(),2000);}
 async function pollJob(){if(!d.open)return;try{showJob(await request('batch-status?id='+encodeURIComponent(job.id)));}catch(e){error(e.message+'；不要重复创建，请用“查看最近批次”核查结果。');}}
 $('#batch-query').onclick=()=>void load();$('#batch-preset').onchange=()=>{const r=datePreset($('#batch-preset').value);if(r){$('#batch-from').value=r.from;$('#batch-to').value=r.to;void load();}};
 for(const id of ['#batch-from','#batch-to'])$(id).onchange=()=>{$('#batch-preset').value='custom';data=null;selected.clear();$('#batch-range-state').textContent='日期已修改，请点击“查询区间数据”。';render();};
 $('#batch-pick').onclick=()=>{for(const p of matched.slice((page-1)*20,page*20)){if(selected.size>=BATCH_LIMIT&&!selected.has(p.id)){notify('单批最多20条，请分批处理');break;}selected.add(p.id);}render();};$('#batch-clear').onclick=()=>{selected.clear();render();};$('#batch-prune').onclick=()=>{const allowed=new Set(matched.map(p=>p.id));selected=new Set([...selected].filter(id=>allowed.has(id)));render();};
 for(const node of d.querySelectorAll('.batch-filters input,.batch-filters select'))node.addEventListener('input',()=>{page=1;render();});$('#batch-budget').oninput=render;
 d.addEventListener('change',e=>{if(e.target.dataset.pick){const id=e.target.dataset.pick;if(e.target.checked&&selected.size>=BATCH_LIMIT){e.target.checked=false;notify('单批最多20条');return;}e.target.checked?selected.add(id):selected.delete(id);render();}});
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')&&!working)d.close();if(b.dataset.batchPage){page=Number(b.dataset.batchPage);render();}});
 $('#batch-back').onclick=()=>{prepared=null;delete $('#batch-primary').dataset.failed;$('#batch-review').hidden=true;$('.batch-selection').hidden=false;$('#batch-back').hidden=true;$('#batch-primary').textContent='核对所选计划';render();};
 $('#batch-primary').onclick=async()=>{
  if(working||loading)return;working=true;$('#batch-primary').disabled=true;error('');$('.batch-selection').inert=true;
  try{if(!await ensureOperator()){working=false;$('.batch-selection').inert=false;render();return;}}catch(e){working=false;$('.batch-selection').inert=false;error(e.message);$('#batch-primary').disabled=false;return;}
  try{if(!prepared){if(!data||!selected.size)throw new Error('请先查询并勾选计划');const q={accountId:ACCOUNT_ID,ids:[...selected],budget:$('#batch-budget').value,duration:$('#batch-duration').value,namePrefix:$('#batch-name').value};$('#batch-primary').textContent='正在逐条核对…';const p=await request('batch-prepare',q);if(!p.canSubmit){throw new Error(p.items.filter(i=>i.error).map(i=>`${i.name}：${i.error}`).join('；')||'当前连接不能提交');}prepared=p;$('.batch-selection').hidden=true;$('#batch-review').hidden=false;$('#batch-back').hidden=false;$('#batch-review').innerHTML=`<h3>确认这 ${p.items.length} 条计划</h3><p>统计筛选区间：${data.from} 至 ${data.to}</p><p class="confirmation-summary">每条额外预算 ${esc(q.budget)} 元，时长 ${esc(q.duration)} 小时；合计 ${p.totalBudget.toFixed(2)} 元。</p><p>这是额外调控预算。确认后会在真实账户逐条创建任务；任一失败或结果不明确时停止后续计划，不自动重试。确认有效期5分钟。</p><ul>${p.items.map(i=>`<li><b>${esc(i.name)}</b><small> ID：${i.id}</small><p>${esc(i.description)}</p></li>`).join('')}</ul>`;$('#batch-primary').textContent='确认批量创建';}
   else{if(prepared.expiresAt<=Date.now())throw new Error('确认已过期，请返回重新核对');try{localStorage.setItem(storageKey,prepared.token);}catch{}const result=await request('batch-commit',{accountId:ACCOUNT_ID,token:prepared.token,confirmed:true});showJob(result);}
  }catch(e){error(e.message);$('#batch-primary').textContent=prepared?'请先查看最近批次或返回重核':'重新核对';if(prepared)$('#batch-primary').dataset.failed='true';}
  finally{working=false;$('.batch-selection').inert=false;$('#batch-primary').disabled=Boolean($('#batch-primary').dataset.failed);}
 };
 $('#batch-cancel-job').onclick=async()=>{try{clearTimeout(timer);showJob(await request('batch-cancel',{id:job.id}));}catch(e){error(e.message);}};
 $('#batch-history').onclick=async()=>{if(working)return;try{if(!await ensureOperator())return;const id=localStorage.getItem(storageKey);if(!id)throw new Error('当前浏览器没有记录批次');clearTimeout(timer);showJob(await request('batch-status?id='+encodeURIComponent(id)));}catch(e){error(e.message);}};
 d.addEventListener('cancel',e=>{if(working)e.preventDefault();});d.addEventListener('close',()=>{revision++;clearTimeout(timer);d.remove();});void load();
}
